{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Donepezil, which shares a dimethoxyaromatic ketone and a basic amine side chain with the query, has an absolute oral bioavailability of 100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Valbenazine, a tetrabenazine-derived VMAT2 inhibitor with a modified core, has an absolute oral bioavailability of approximately 49% in humans, showing that tetrabenazine-like dimethoxy scaffolds can achieve F ≥ 20% when the metabolic liability is modified.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Verapamil, which shares two dimethoxyphenyl groups and a tertiary amine with the query, has an absolute oral bioavailability of 34% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Tetrabenazine, the closest analogue by Morgan similarity, has a very low mean oral systemic availability of 0.049 in patients, but its low F is driven by rapid ketone reduction, a liability absent in the query's lactam.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C45"],
      "claim": "Almorexant, which contains a dimethoxytetrahydroisoquinoline and an amide, has an absolute oral bioavailability of 11.2% in healthy subjects, but its low F is associated with a lipophilic trifluoromethylphenyl group and poor absorption, features not present in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%) with moderate confidence; the query's lactam and basic tertiary amine side chain are more consistent with high-F analogues (donepezil, valbenazine, verapamil) than with low-F tetrabenazine/almorexant, whose key metabolic/physicochemical liabilities are absent.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Low Morgan similarities (<0.38) limit quantitative transferability.",
    "Unknown metabolic stability of the lactam and extent of O-demethylation/N-dealkylation in humans.",
    "No data on solubility, permeability, or first-pass extraction for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

